#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.0037345750000000004, 0.393474725, 0.158601335], 'basis': [[0.0, 0.9997368455702719, 0.022939913016455156], [-0.9608518551315373, 0.006355793110369625, -0.2769897405757505], [-0.27706265083963116, -0.022041857978417036, 0.9605990027095469]], 'axis': [0.022939913016455156, -0.2769897405757505, 0.9605990027095469], 'zmin': -0.03664028474742734, 'zmax': 0.05888112130048978, 'profiles': [{'outer': [[-0.10007166189398777, -0.028858358545808885], [-0.10014162375654632, 0.027353155546290277], [-0.10007876865459113, 0.029435592686453144], [-0.09994588732605798, 0.02975618692951929], [-0.09977673730472486, 0.029913522991490353], [-0.09950728691340116, 0.030010360972352292], [-0.09782786073023099, 0.030171640196039264], [-0.09344083559533538, 0.030509941547445674], [-0.009463550285082558, 0.036820915250880895], [-0.007160929961089877, 0.03687668006621621], [0.004526295037132997, 0.03690924400295528], [0.005256306178477233, 0.03646511582802782], [0.005755290324624972, 0.03510860552451534], [0.00580882541278395, 0.03469846939239953], [0.00845792227226029, 0.0347711956011068], [0.0094217583734075, 0.03484628963674439], [0.01015728751594011, 0.03498913907787677], [0.0113404663173002, 0.03714228339533216], [0.011690085994459372, 0.03732028402921336], [0.025016338240376787, 0.03736192900703263], [0.052176364805859306, 0.03922870000179202], [0.0762090048028204, 0.041253360831837595], [0.07886465417084719, 0.041230401690038054], [0.08043516600057249, 0.04097293867589171], [0.081299281888462, 0.040712960748778046], [0.08224250379529315, 0.04029714047217114], [0.08333527135671873, 0.03970939066194748], [0.08455100437646042, 0.03893542581651685], [0.08718769843541942, 0.03692467054337671], [0.09059194562339207, 0.034024596569493484], [0.0929039592209207, 0.031205228992062305], [0.09408426639462221, 0.02947940604302523], [0.09551303279401968, 0.026962776713346074], [0.09712807766223229, 0.0234444037232117], [0.09890475235971045, 0.018713882285229133], [0.10061778468760772, 0.01288956347387953], [0.10183891026295262, 0.006661004620119954], [0.1023559641301197, 0.00011021979805165748], [0.10185961139974184, -0.006429182827726228], [0.1006458608209488, -0.012672776498463247], [0.09901086824566653, -0.018311185187039208], [0.0972506370591202, -0.023047614160715182], [0.09563708931724864, -0.026584597432827428], [0.09421948303576233, -0.02910797069158343], [0.09304810297604085, -0.030839698270180026], [0.0907410045190612, -0.033673159662455196], [0.08855748876554445, -0.03561505106628613], [0.08588649458244955, -0.03779975359939366], [0.08457970020905285, -0.038775714427395386], [0.08338477295024568, -0.03955280464704483], [0.08230079010272724, -0.040144355909518405], [0.0813639434381822, -0.04056361715444459], [0.08052106849678875, -0.04083918887271421], [0.07884925545582644, -0.0411159938643532], [0.0767600103305344, -0.04114345425857355], [0.07558538434618826, -0.041083298329731385], [0.05232509202568816, -0.03916407286780865], [0.025011612795826352, -0.03734739863711708], [0.023123490834401406, -0.037297132019487894], [0.011766413542841705, -0.03733261439855607], [0.011606131831764439, -0.03729525379452244], [0.011320212457264408, -0.037087587207047835], [0.009557496525620301, -0.0346016045375974], [0.008691315490768198, -0.03453602656126389], [0.005933760514070223, -0.03447876047868486], [0.005864212649634131, -0.0350417126273347], [0.005357960184106121, -0.03642890832435294], [0.005277200095158342, -0.036536204874008806], [0.004561744646644127, -0.03698111626007767], [-0.009375179165712446, -0.03695408866817517], [-0.07124371717999171, -0.032621521824214905], [-0.09947506973828221, -0.030586302412112163], [-0.09975316523188989, -0.030493687579286884], [-0.09991784093864622, -0.03034936112587719], [-0.09999652801860297, -0.030168316236029058]], 'holes': []}], 'simplify_tolerance': 4.0502109964106024e-05, 'sketch_entity_count': 126}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
